import{_ as t,o,c as n,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Connector Framework","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/connector-framework.md","filePath":"sovereign-edge/epics/connector-framework.md"}'),a={name:"sovereign-edge/epics/connector-framework.md"};function i(s,e,c,l,d,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="epic-connector-framework" tabindex="-1">Epic: Connector Framework <a class="header-anchor" href="#epic-connector-framework" aria-label="Permalink to &quot;Epic: Connector Framework&quot;">​</a></h1><blockquote><p>The manifest schema, permission/consent model, tool-routing, and tiered trust runtime that every connector — first-party or, eventually, third-party — is built on.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>📋 Planned</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This is the foundation research 0001 calls out as needing to be right from Phase 1: even though only one connector (Search) exists at first and it&#39;s hardcoded, it must already be expressed in the same shape a downloaded, third-party connector will use in Phase 3. Getting this epic right is what lets Phase 2 and Phase 3 be purely additive.</p><p>Three trust tiers, per CONCEPT.md:</p><ul><li><strong>Tier 1</strong> — declarative manifest only (tool schema, endpoint, auth, request/response templates). No code. Open to third parties in Phase 3.</li><li><strong>Tier 2</strong> — a sandboxed transform script on top of Tier 1. Open to third parties in Phase 3, once a real use case justifies building it.</li><li><strong>Tier 3</strong> — first-party native OS integration. Not opened to third parties in this project&#39;s current scope.</li></ul><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-2-1-—-connector-manifest-schema-tier-1" tabindex="-1">📋 2.1 — Connector manifest schema (Tier 1) <a class="header-anchor" href="#📋-2-1-—-connector-manifest-schema-tier-1" aria-label="Permalink to &quot;📋 2.1 — Connector manifest schema (Tier 1)&quot;">​</a></h4><p><strong>Goal:</strong> Define the declarative shape every Tier 1 connector — first-party or third-party — conforms to.</p><p><strong>Deliverables:</strong></p><ul><li>Schema fields: <code>id</code>, <code>name</code>, <code>version</code>, <code>tier</code>, <code>tool</code> (name + JSON schema for the LLM&#39;s function-call), <code>permissions</code> (declared network domain, credential storage), <code>endpoint</code>/<code>request</code>/<code>response</code> templates, <code>pricing</code>, <code>platforms</code>.</li><li>A validator (used both at connector-author time and at load time).</li><li>Written and versioned even though only one connector uses it in Phase 1 — this is the piece Phase 3 reuses without a rewrite.</li></ul><p><strong>Dependencies:</strong> none within this epic — first task.</p><p><strong>Review checklist:</strong></p><ul><li>The Search connector (epic 3) validates against this schema with no special-casing.</li></ul><hr><h4 id="📋-2-2-—-permission-and-consent-model" tabindex="-1">📋 2.2 — Permission and consent model <a class="header-anchor" href="#📋-2-2-—-permission-and-consent-model" aria-label="Permalink to &quot;📋 2.2 — Permission and consent model&quot;">​</a></h4><p><strong>Goal:</strong> Per-connector, explicit, revocable permission grants — never a blanket &quot;this app can use the network&quot; toggle.</p><p><strong>Deliverables:</strong></p><ul><li>Grant/revoke UI per connector.</li><li>Per-connector scoped credential storage (OS keychain), isolated so one connector&#39;s token is never visible to another.</li><li>A settings surface listing every installed connector and its current permission state.</li></ul><p><strong>Dependencies:</strong> Task 2.1.</p><p><strong>Review checklist:</strong></p><ul><li>Revoking one connector&#39;s permission does not affect any other connector&#39;s access or stored credentials.</li></ul><hr><h4 id="📋-2-3-—-tool-routing-intent-detection-layer" tabindex="-1">📋 2.3 — Tool-routing / intent-detection layer <a class="header-anchor" href="#📋-2-3-—-tool-routing-intent-detection-layer" aria-label="Permalink to &quot;📋 2.3 — Tool-routing / intent-detection layer&quot;">​</a></h4><p><strong>Goal:</strong> Let the local model decide &quot;this needs a connector&quot; vs. &quot;just answer in chat,&quot; and pick the right one.</p><p><strong>Deliverables:</strong></p><ul><li>Prompt/grammar-constrained decoding (e.g. GBNF-style grammar via <code>llama.cpp</code>) so tool-call output is reliably valid JSON even from a small on-device model — small models are not reliable free-form tool-callers without this constraint.</li><li>Fallback behavior when no connector matches or the matching connector lacks permission (explain to the user what&#39;s needed, don&#39;t silently fail).</li></ul><p><strong>Dependencies:</strong> Task 2.1, Task 1.1 (inference engine).</p><p><strong>Review checklist:</strong></p><ul><li>A request that should trigger a connector call produces valid, schema- conformant tool-call output in a controlled test set, not just &quot;it usually works.&quot;</li></ul><hr><h4 id="📋-2-4-—-connector-runtime-host" tabindex="-1">📋 2.4 — Connector runtime host <a class="header-anchor" href="#📋-2-4-—-connector-runtime-host" aria-label="Permalink to &quot;📋 2.4 — Connector runtime host&quot;">​</a></h4><p><strong>Goal:</strong> Execute a validated tool call against a Tier 1 connector&#39;s manifest.</p><p><strong>Deliverables:</strong></p><ul><li>Request/response template execution (map the LLM&#39;s structured call into an HTTP request per the manifest, map the HTTP response back into text/ data for the model).</li><li>Reserved extension points for Tier 2 (sandboxed script execution) and Tier 3 (native module dispatch), even if unimplemented until epic 5/9 needs them.</li></ul><p><strong>Dependencies:</strong> Task 2.1, Task 2.2, Task 2.3.</p><p><strong>Review checklist:</strong></p><ul><li>A Tier 1 connector&#39;s manifest alone (no connector-specific code) is enough to execute a real request/response round trip.</li></ul><hr><h4 id="📋-2-5-—-in-chat-connector-provenance" tabindex="-1">📋 2.5 — In-chat connector provenance <a class="header-anchor" href="#📋-2-5-—-in-chat-connector-provenance" aria-label="Permalink to &quot;📋 2.5 — In-chat connector provenance&quot;">​</a></h4><p><strong>Goal:</strong> Make it visible in the UI which connector (if any) answered a given message — per CONCEPT.md&#39;s &quot;always show which trust tier is active.&quot;</p><p><strong>Deliverables:</strong></p><ul><li>A visible marker in chat distinguishing a fully-offline reply from one that used a specific named connector.</li></ul><p><strong>Dependencies:</strong> Task 2.4, Task 1.3 (chat UI).</p><p><strong>Review checklist:</strong></p><ul><li>A user can tell, without opening settings, whether a given reply touched the network and which connector did it.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><ul><li>The Search connector (epic 3) and Sovereign Tasks connector (epic 4) are the first consumers of this framework.</li><li>Epic 5 (Connector Store &amp; SDK) reuses this framework&#39;s manifest schema unchanged when opening it to third parties.</li></ul>',52)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
